recipes.code:
{
  "inputs": [
    {
      "id": "tessera-api-key",
      "type": "promptString",
      "description": "API key in tk_* format. Get one free at https://tesseraai.io/dev.",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@tessera-llm/mcp-server@0.1.2"
      ],
      "env": {
        "TESSERA_API_KEY": "${input:tessera-api-key}",
        "TESSERA_UPSTREAM_API_BASE_URL": "https://ledger.tesseraai.io"
      }
    }
  }
}
